export class HomeComponent {
  constructor(propertyService, router) {
    this.propertyService = propertyService;
    this.router = router;
    // 📊 ESTADO
    this.isLoading = true;
    this.searchError = null;
    // 🔍 FORM DATA - ✅ INICIALIZACIÓN CORREGIDA
    this.searchData = {
      destination: '',
      checkIn: '',
      checkOut: '',
      guests: 2
    };
    // 🧹 CLEANUP
    this.destroy$ = new Subject();
    // 📅 COMPUTED PROPERTIES
    this.today = new Date().toISOString().split('T')[0];
    this.tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];
    // 🚀 CONFIGURACIONES ESTÁTICAS
    this.quickSuggestions = QUICK_SUGGESTIONS;
    this.zonasDelNorte = Object.entries(ARMENIA_NORTH_ZONES).map(([key, value]) => ({
      key: key,
      ...value,
      properties: this.getPropertiesCountByZone(key)
    }));
    this.propertyTypeLabels = PROPERTY_TYPE_LABELS;
    // ✅ SOLO obtener el observable, la inicialización va en ngOnInit
    this.featuredProperties$ = this.propertyService.getFeaturedProperties();
  }
  ngOnInit() {
    // ✅ ÚNICA llamada a inicialización
    this.initializeDefaultDates();
    this.loadFeaturedProperties();
  }
  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }
  // ================================
  // 🔧 INICIALIZACIÓN
  // ================================
  initializeDefaultDates() {
    // ✅ INICIALIZAR fechas por defecto para que el formulario funcione
    this.searchData.checkIn = this.getDateString(1); // Mañana
    this.searchData.checkOut = this.getDateString(3); // Pasado mañana
  }
  getDateString(daysFromNow) {
    const date = new Date();
    date.setDate(date.getDate() + daysFromNow);
    return date.toISOString().split('T')[0];
  }
  // ================================
  // 🔄 DATA LOADING
  // ================================
  loadFeaturedProperties() {
    // Simular loading realista
    setTimeout(() => {
      this.isLoading = false;
    }, 800);
    this.featuredProperties$.pipe(takeUntil(this.destroy$)).subscribe({
      next: properties => {
        this.isLoading = false;
        console.log('✅ Habitaciones del Norte de Armenia cargadas:', properties.length);
      },
      error: error => {
        this.isLoading = false;
        this.searchError = 'Error cargando habitaciones. Inténtalo de nuevo.';
        console.error('❌ Error cargando habitaciones:', error);
      }
    });
  }
  // ================================
  // 🔍 SEARCH FUNCTIONALITY
  // ================================
  onSearchSubmit(form) {
    console.log('🔍 Formulario enviado:', {
      formValid: form.valid,
      searchData: this.searchData
    });
    // Limpiar errores previos
    this.searchError = null;
    // Validación
    if (!this.validateSearchData()) {
      console.log('❌ Validación fallida:', this.searchError);
      return;
    }
    console.log('✅ Validación exitosa, ejecutando búsqueda...');
    this.performSearch(this.searchData);
  }
  validateSearchData() {
    const {
      destination,
      checkIn,
      checkOut,
      guests
    } = this.searchData;
    // Validar zona requerida
    if (!destination) {
      this.searchError = 'Por favor selecciona una zona del norte de Armenia';
      return false;
    }
    // Validar fechas si están presentes
    if (checkIn && checkOut) {
      const checkInDate = new Date(checkIn);
      const checkOutDate = new Date(checkOut);
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (checkInDate < today) {
        this.searchError = 'La fecha de llegada no puede ser anterior a hoy';
        return false;
      }
      if (checkOutDate <= checkInDate) {
        this.searchError = 'La fecha de salida debe ser posterior a la fecha de llegada';
        return false;
      }
    }
    // Validar huéspedes
    if (!guests || guests < 1) {
      this.searchError = 'Debe haber al menos 1 huésped';
      return false;
    }
    return true;
  }
  performSearch(params) {
    const queryParams = {
      destination: params.destination,
      checkIn: params.checkIn,
      checkOut: params.checkOut,
      guests: params.guests.toString()
    };
    console.log('🚀 Navegando a search-results con:', queryParams);
    this.router.navigate(['/search-results'], {
      queryParams
    }).then(success => {
      if (success) {
        console.log('✅ Navegación exitosa a search-results');
      } else {
        console.error('❌ Error en navegación');
        this.searchError = 'Error en la navegación. Inténtalo de nuevo.';
      }
    });
  }
  // ✅ MÉTODO PARA QUICK SUGGESTIONS
  searchDestination(destination) {
    console.log('🎯 Búsqueda rápida por zona:', destination);
    // Actualizar datos de búsqueda
    this.searchData = {
      destination,
      checkIn: this.getDateString(1),
      checkOut: this.getDateString(3),
      guests: 2
    };
    // Realizar búsqueda
    this.performSearch(this.searchData);
  }
  // ================================
  // 🏠 PROPERTY ACTIONS
  // ================================
  viewPropertyDetails(propertyId) {
    console.log('🏠 Ver detalles de habitación:', propertyId);
    // Incrementar vistas si el servicio lo soporta
    if (this.propertyService.incrementPropertyViews) {
      this.propertyService.incrementPropertyViews(propertyId).pipe(takeUntil(this.destroy$)).subscribe();
    }
    this.router.navigate(['/property', propertyId]);
  }
  toggleFavorite(propertyId, event) {
    event.stopPropagation();
    console.log('❤️ Toggle favorito para habitación:', propertyId);
    if (this.propertyService.toggleFavorite) {
      this.propertyService.toggleFavorite(propertyId).pipe(takeUntil(this.destroy$)).subscribe({
        next: isFavorite => {
          console.log(`${isFavorite ? '❤️' : '🤍'} Favorito actualizado`);
        },
        error: error => console.error('❌ Error actualizando favorito:', error)
      });
    }
  }
  // ================================
  // 🗺️ NAVIGATION - ✅ CORREGIDA
  // ================================
  viewAllProperties() {
    this.router.navigate(['/search-results'], {
      queryParams: {
        area: 'armenia-norte'
      }
    });
  }
  viewPropertiesByZone(zone) {
    this.router.navigate(['/search-results'], {
      queryParams: {
        destination: zone,
        area: 'armenia-norte'
      }
    });
  }
  // ================================
  // 🛠️ UTILITY FUNCTIONS
  // ================================
  trackByPropertyId(index, property) {
    return property.id;
  }
  getPropertyTypeName(property) {
    return this.propertyTypeLabels[property.propertyType] || 'Alojamiento';
  }
  getPropertyTypeLabel(propertyType) {
    return this.propertyTypeLabels[propertyType] || 'Alojamiento';
  }
  getPropertyFeatures(property) {
    if (property?.features && property.features.length > 0) {
      return property.features.slice(0, 3);
    }
    // Features por defecto basados en el tipo
    switch (property.propertyType) {
      case 'habitacion':
        return ['Baño privado', 'WiFi gratis', 'Ventana exterior'];
      case 'apartamento':
        return ['Cocina equipada', 'Sala de estar', 'WiFi gratis'];
      case 'studio':
        return ['Concepto abierto', 'Cocina integrada', 'Balcón'];
      case 'casa':
        return ['Múltiples habitaciones', 'Patio privado', 'Parqueadero'];
      case 'penthouse':
        return ['Vista panorámica', 'Terraza privada', 'Lujo'];
      default:
        return ['WiFi gratis', 'Limpieza incluida'];
    }
  }
  getZoneName(zone) {
    return ARMENIA_NORTH_ZONES[zone]?.name || zone;
  }
  getZoneDescription(zone) {
    return ARMENIA_NORTH_ZONES[zone]?.description || '';
  }
  formatPrice(price) {
    return new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0
    }).format(price);
