  // 🗺️ NAVIGATION - ✅ CORREGIDA
  // ================================

  viewAllProperties(): void {
    this.router.navigate(['/search-results'], {
      queryParams: {
        area: 'armenia-norte'
      }
    });
  }

  viewPropertiesByZone(zone: ZoneType): void {
    this.router.navigate(['/search-results'], {
